sections.css:
.legacy-we-grid__title {
  font-family: Montserrat, sans-serif;
  font-size: 14px;
  font-weight: 700;
  color: #333;
  margin: 0 0 14px;
}

.legacy-we-grid__wrap {
  font-family: Montserrat, sans-serif;
  overflow-x: auto;
}
.legacy-we-grid {
  border-collapse: collapse;
  width: 100%;
  font-size: 13px;
  background: #fff;
}
.legacy-we-grid th {
  background: transparent;
  border: 1px solid #ddd;
  padding: 5px 8px;
  text-align: left;
  font-weight: 700;
  color: #333;
  white-space: nowrap;
}
.legacy-we-grid td {
  border: 1px solid #ddd;
  padding: 5px 8px;
  vertical-align: top;
  color: #333;
}
.legacy-we-grid tbody tr:hover {
  background: #f5f9fc;
}
.legacy-we-grid a {
  color: #007090;
  text-decoration: none;
}
.legacy-we-grid a:hover {
  text-decoration: underline;
}
.legacy-we-grid__desc {
  max-width: 320px;
}
.legacy-we-grid__num {
  text-align: right;
  white-space: nowrap;
}
.legacy-we-grid__dotcell {
  text-align: center;
}
.legacy-we-grid__hdcol {
  background: #eaf6fa;
}
.legacy-dot {
  display: inline-block;
  width: 10px;
  height: 10px;
  border-radius: 50%;
}
.legacy-dot--filled {
  background: #007090;
}
.legacy-dot--ring {
  background: transparent;
  border: 2px solid #007090;
}
.legacy-panel {
  background: #fff;
  border: 1px solid transparent;
  border-radius: 4px;
  box-shadow: 0 1px 1px #0000000d;
  margin: 0 0 20px;
}
